#include "CapabilityTierMatrix.hpp"
namespace RawrXD::Governance {namespace{constexpr TierPolicy P[]={{CapabilityTier::Emergency,2048,4,false,false,false,1,1,"Emergency"},{CapabilityTier::Minimal,4096,4,false,false,false,1,1,"Minimal"},{CapabilityTier::Compact,8192,8,true,false,false,1,3,"Compact"},{CapabilityTier::Standard,16384,8,true,true,false,1,7,"Standard"},{CapabilityTier::High,32768,8,true,true,true,2,14,"High"},{CapabilityTier::Maximum,65536,16,true,true,true,4,32,"Maximum"}};}
const TierPolicy&CapabilityTierMatrix::policy(CapabilityTier t)noexcept{return P[(unsigned)t<=5?(unsigned)t:0];}
TierDecision CapabilityTierMatrix::resolve(const HardwareSnapshot&h)const noexcept{double s=0;if(h.total_ram_bytes>=64ull<<30)s+=30;else if(h.total_ram_bytes>=32ull<<30)s+=22;else if(h.total_ram_bytes>=16ull<<30)s+=12;if(h.total_vram_bytes>=48ull<<30)s+=40;else if(h.total_vram_bytes>=24ull<<30)s+=30;else if(h.total_vram_bytes>=12ull<<30)s+=20;else if(h.total_vram_bytes>=6ull<<30)s+=10;if(h.cpu.avx512f)s+=15;else if(h.cpu.avx2)s+=8;if(h.gpu_count)s+=10;if(h.ram_headroom()<.05||(h.total_vram_bytes&&h.vram_headroom()<.05))return{policy(CapabilityTier::Emergency),s,"critical hardware headroom"};CapabilityTier t=CapabilityTier::Minimal;if(s>=70)t=CapabilityTier::Maximum;else if(s>=55)t=CapabilityTier::High;else if(s>=40)t=CapabilityTier::Standard;else if(s>=25)t=CapabilityTier::Compact;return{policy(t),s,"capability score"};}
}
